    "address": "1401 Greenbrier Parkway, Chesapeake, VA, 23320",
    "description": "CCCHR Presents January - Mystery Cruise Postponed Due to WEATHER DATE TBD Saturday, February 21st | 9:30a-2p Meet at Greenbriar Mall - Infront of the Old Sears Building at 9:30a 1401 Greenbrier Pkwy, Chesapeake, VA 23320 Come join us for the January Mystery Cruise. OPEN TO ALL CLUBS, MEMBERS, AND SOLO RIDERS! ALL MAKES AND MODELS! bring the daily and let's ride! Our route will be provided in the morning before we depart. This is a great way to meet new friends, get your car/truck out of winter storage and have some fun. We will meet at Greenbrier Mall at 0930 in front of the old Sears, with a departure at 1000 for our destination. Come with a full tank of fuel. This trip will be approximately 2 hours one way to our destination. We will divide up into groups of 5-7 cars with a lead car who is responsible for that group. This Mystery Cruise will be canceled in the event of inclement weather. This is a Sunshine only event!! More Info",
