    "address": "West Military Highway, Chesapeake, VA",
    "description": "The Mustang Club of Tidewater’s Annual Spring Fling Mustang Birthday Car Show - All Makes and Models Welcome!!! Date: Saturday, April 18th, 2026 | 9a-2p Location: Cavalier Ford Greenbrier - 1515 S. Military Highway, Chesapeake, VA 23320 Click on the header image to see the entire show flyer! Details: | • This is a Participant's Choice show, with 25 Participant’s Choice awards, and 4 top awards for Best in Show, Dealer’s Choice, Charity's Choice, and Club/Group Participation. | • Open to all years, makes and models of passenger cars, trucks, and motorcycles. Come show us what you have!!! | • This is a family friendly event, so feel free to bring the kids so they can enjoy the show! Bring your cameras! | • There is no charge for spectators, but they must park adjacent to but not in the show field, as directed. | • There will be food vendors on-site and hot dogs & chips provided by Cavalier Ford. | • 50/50 tickets will be sold during the show with winners of various prizes chosen during awards. | • Please be respectful of our host, Cavalier Ford Greenbrier. NO loud music/bass, engine revving, or exhibitions of speed at or departing the show by attendees. Schedule: | • 9:00 - Registration Opens | • 10:00 - Driver's Meeting / Judging Begins | • 12:00 - Registration Closed | • 12:30 - Judging Ends / Votes Counted | • 1:30 - Car Show Awards Presented and 50/50 Winners announced | • 2:00 - Show Ends",
