    "address": "4024 Portsmouth Boulevard, Chesapeake, VA, 23321",
    "description": "(Weekly) Thursday Night Cruise-In at the DQ Thursday, June 11th | 3p Located at Dairy Queen - 4024 Portsmouth Blvd., Chesapeake So if you're not doing anything on Thursday afternoons get those cars out and come up to DQ. You can go in and order food and bring it out to eat. Make sure you bring a chair because they've taken the tables and chairs in. People start getting there around 2:00 and hang out for 3-4 hours or so. The weather is starting to get nice and there's not a whole lot of places we can go. This is one of the few places we can.",
