    "source": "CCCHR",
    "city": "Williamsburg",
    "venue": "Bruster's Real Ice Cream",
    "address": "5289 John Tyler Highway, Williamsburg, VA, 23185",
    "description": "(Weekly) Colonial Car Scene Meet Friday, June 12th | 7-10p Located at Bruster's Real Ice Cream, 5289 John Tyler Hwy., Williamsburg. FRIDAY! FRIDAY! FRIDAY! Friday nights, come on out and have a good time, trying get the dust off the camera with the sun being out for a good bit at the start and need some new photos for the flyers. As always respect the spot, it's been weeks since I've been able to come out and don't want to show up just to see some ding dongs being ding dongs ruining it. Keep in mind that being around in ice cream establishment there are going to be children so please remain respectful! Hope to see you all out there this week. No Revving - No Burnouts - No Loud Music. Pick-up after yourself. Hope to see you all there.",
