    "city": "Chesapeake",
    "venue": "Everbowl",
    "address": "1244 Old Greenbrier Road, Chesapeake, VA, 23320",
    "description": "[2nd sat] Cars and Coffee Chesapeake Saturday, June 13th | 8a-11a Located at Everbowl - 1244 Greenbrier Pkwy #570, Chesapeake, VA 23320 Team Ultraspeed and Everbowl are teaming up to bring you the best Cars and Coffee meets in the area! Come hangout and help us close out the 2025 Car Season. We are collecting non-perishable goods this month for the Foodbank of Southwestern VA. Give Thanks, Give Food. Help us drive out hunger! We are also still collecting new kids pajamas to support Pajama Jams. Pajama Jams collects these items throughout the year in preparation for their important Annual Holiday Pajama Drive for Hampton Roads. Please drop off your donations at the Red Ultraspeed tent, you can write it off on your taxes! We are now a 501(C)3! You won't want to miss this, so mark your calendars and we'll see you there! More info",
