    "description": "(Weekly) 2026 Classic Cars, Coffee, & Cones at the Portsmouth Olde Towne Farmers Market Saturday, june 13th | 10a-1:30p Located at the Courthouse and High St., Portsmouth. Join us for informal Classic Cars & Coffee at the historic Olde Towne Farmers Market every Saturday through December 20th. Classic cars get FREE up-front, car-show-style parking and FREE gourmet coffee for the drivers. Great spot to bring the spouse and family, 50+ vendors with fresh produce, grilled items, baked goods, sweets, juices, confections, even handmade jewelry and artisan items. Always something different, and very welcoming! Just flag down anyone in a yellow traffic safety vest and our deputy sheriffs will guide you to a prime spot.",
