    "address": "1400 South Independence Boulevard, Virginia Beach, VA, 23462",
    "description": "(Twice Weekly) Auto Club Meetup by the Retired Cruisers Club of America Saturday, June 20th | 7-10p Located at 1400 S. Independence Blvd., Virginia Beach. Hello auto family. Come out to Freedom Wash in VB for Friday and Saturday car meets. We think it will be cool to meet people in the Norfolk And Virginia beach area with ex police vehicles and some nice Hot Rodz. All different rides are welcome. Get a wash for only $5 and get a spot for you ride if you're looking to sell quick. We are trying to recruit new members as well and we would love to get some new supporters to help get The R.C.C name out there. if interested plz drop pic of your ride or hit us up - TY.",
