    "description": "(Weekly) Doumar's cruise-in Hosted by The Mustang and Ford Association of Virginia Wednesday, November 4th | 6-8p Located at Doumar's Cones & Barbecue, 1919 Monticello Ave., Norfolk. Please join us for some cars at a weekly cruise-in every Wednesday night until it gets cold, all are invited! Bring your rides out and have some fun. They are open during these hours, so enjoy all the great eats and drinks they provide, including their amazing ice cream and handmade cones! Be kind, clean up after yourselves, no excessive revving, and no burnouts and do not speed off when leaving their parking lot. Hope to see you there! More Info",
